import { select, dispatch, subscribe, resetDemoData } from './store.js';
import { t, L, esc } from './i18n.js';
import { PERSONAS } from './data.js';
import { ROLE_HOMES, QUICK_JUMPS } from './layout.js';
import { navigate } from './router.js';
import { icon } from './icons.js';
import { modal, button, openOverlay, closeOverlay } from './ui.js';
export function mountSwitcher(root) {
 const roles=['visitor','student','guardian','teacher','assistant','admin_finance','admin_moderation','super_admin'];let disposed=false;
 function draw() { if(disposed)return;closeOverlay('reset-demo');closeOverlay('demo-controls');const pref=select('preferences');root.innerHTML=`<button type="button" class="switcher-trigger btn-primary" data-switcher="toggle" aria-label="${esc(t('switcherOpen'))}" title="${esc(t('switcherOpen'))}" aria-expanded="false" aria-controls="demo-controls">${icon('users',{size:26})}</button><dialog id="demo-controls" class="switcher-panel" aria-labelledby="switcher-title"><div class="flex items-center justify-between gap-2"><h2 id="switcher-title" tabindex="-1" class="text-lg">${esc(t('switcher'))}</h2><button type="button" class="icon-btn" data-switcher="close" aria-label="${esc(t('close'))}">${icon('x')}</button></div><p class="text-sm muted mt-1">${esc(t('switcherIntro'))}</p><p class="text-sm font-semibold mt-4 mb-2">${esc(t('roles'))}</p><div class="space-y-1">${roles.map(role=>`<button type="button" class="role-option" data-switcher="role" data-role="${role}" aria-pressed="${role===pref.role}"><span class="text-primary">${icon(role==='visitor'?'globe':role.startsWith('admin')||role==='super_admin'?'shield':role==='student'?'graduationCap':role==='guardian'?'users':'user')}</span><span class="min-w-0"><span class="block text-sm font-semibold">${esc(t('role.'+role))}</span><span class="block text-xs muted">${esc(L(PERSONAS[role].name))}</span></span>${role===pref.role?`<span class="ms-auto text-primary">${icon('check',{size:16})}</span>`:''}</button>`).join('')}</div><div class="border-t border-border mt-4 pt-3"><p class="text-sm muted mb-2">${esc(t('language'))}</p><div class="flex gap-2">${[['ar','العربية'],['en','English']].map(([lang,label])=>`<button type="button" class="btn flex-1 ${pref.lang===lang?'btn-primary':'btn-secondary'}" data-switcher="lang" data-lang="${lang}" aria-pressed="${pref.lang===lang}">${label}</button>`).join('')}</div><p class="text-sm muted mt-3 mb-2">${esc(t('theme'))}</p><div class="flex gap-2">${['light','dark'].map(theme=>`<button type="button" class="btn flex-1 ${pref.theme===theme?'btn-primary':'btn-secondary'}" data-switcher="theme" data-theme="${theme}" aria-pressed="${pref.theme===theme}">${icon(theme==='light'?'sun':'moon',{size:16})}${esc(t(theme))}</button>`).join('')}</div></div><p class="text-sm muted mt-4 mb-2">${esc(t('quick'))}</p><nav class="space-y-1">${QUICK_JUMPS[pref.role].map((path,i)=>`<a class="nav-link" data-switcher="jump" href="#${path}">${icon('chevronEnd',{size:16})}${esc(t(quickTitle(path,pref.role,i)))}</a>`).join('')}</nav><button type="button" class="btn btn-ghost text-accent mt-3 w-full" data-switcher="reset">${icon('refresh',{size:16})}${esc(t('reset'))}</button></dialog>${modal({id:'reset-demo',title:t('resetTitle'),body:`<p>${esc(t('resetBody'))}</p>`,footer:`<button type="button" class="btn btn-danger" data-switcher="confirm-reset">${esc(t('resetConfirm'))}</button><button type="button" class="btn btn-secondary" data-switcher="cancel-reset">${esc(t('cancel'))}</button>`})}`; }
 function quickTitle(path,role,index) { const p=path.split('?')[0];if(p.includes('/grade/'))return 'route./explore/grade/:gradeId';if(p.includes('/course/'))return 'route.'+p.replace(/C-\d+$/,':id');if(p.includes('/child/'))return 'route./guardian/child/:id';return 'route.'+p; }
 function click(event) { const el=event.target.closest('[data-switcher]');if(!el||!root.contains(el))return;const action=el.dataset.switcher;
 if(action==='toggle') { if(document.getElementById('demo-controls').open)closeOverlay('demo-controls');else openOverlay('demo-controls'); }
 else if(action==='close')closeOverlay('demo-controls');
 else if(action==='role') { if(!roles.includes(el.dataset.role))return;closeOverlay('demo-controls');dispatch('preferences.set',{role:el.dataset.role});navigate('#'+ROLE_HOMES[el.dataset.role]); }
 else if(action==='lang'||action==='theme') { const focused=action;closeOverlay('demo-controls');dispatch('preferences.set',{[action]:el.dataset[action]});openOverlay('demo-controls',{returnFocus:root.querySelector('[data-switcher="toggle"]')});root.querySelector(`[data-switcher="${focused}"][aria-pressed="true"]`)?.focus(); }
 else if(action==='jump') { event.preventDefault();closeOverlay('demo-controls');navigate(el.getAttribute('href')); }
 else if(action==='reset')openOverlay('reset-demo');
 else if(action==='cancel-reset')closeOverlay('reset-demo');
 else if(action==='confirm-reset') { closeOverlay('reset-demo');closeOverlay('demo-controls');resetDemoData();navigate('#'+ROLE_HOMES[select('preferences').role]); }
 }
 draw();root.addEventListener('click',click);const unsub=subscribe(draw);return ()=>{disposed=true;unsub();closeOverlay('reset-demo');closeOverlay('demo-controls');root.removeEventListener('click',click);root.replaceChildren();};
}
